import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'doc', pathMatch: 'full' },
  { path: 'doc/:id', loadComponent: () => import('../../components/individual/individual-doc/individual-doc.component').then(m => m.IndividualDocComponent) }
];
@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class IndividualRoutingModule { }
